import Blockly from 'blockly/core';
import 'blockly/blocks';
import { pythonGenerator } from 'blockly/python';

Blockly.Blocks['array_value'] = {
  init: function() {
    this.appendValueInput('ITEM')
        .setCheck(null) // Có thể đổi thành "String", "Number" nếu muốn
        .appendField("[");
    this.appendDummyInput()
        .appendField("]");
    this.setOutput(true, "Array");
    this.setColour(230); // Đổi màu cố định, ví dụ: xanh dương: 230
    this.setTooltip("Create an array with the given value");
  }
};

// Python Generator
pythonGenerator.forBlock['array_value'] = function(block) {
  const item = pythonGenerator.valueToCode(block, 'ITEM', pythonGenerator.ORDER_ATOMIC) || 'None';
  return [`[${item}]`, pythonGenerator.ORDER_ATOMIC];
};
